// The two generated parts of the specification: spec/statements.json
// (ADR-011 D3 item 7) and the code catalog in 12-findings.md (D3 item 9).
// Both are committed, and both are regenerated by
//
//	go generate ./internal/guarantees
//
// which runs TestGenerateSpec with -spec.generate.

//go:generate go test -count=1 -run=^TestGenerateSpec$ -args -spec.generate

var generateSpec = flag.Bool("spec.generate", false, "rewrite spec/statements.json and the code catalog in spec/12-findings.md")

const (
	// statementsFile is the statement index, below spec/.
	statementsFile = "statements.json"
	// catalogDoc is the chapter that holds the code catalog.
	catalogDoc = "12-findings.md"
	// registryFile is the finding-code registry, below spec/.
	registryFile = "findings/registry.json"
)

// The catalog sits between these two lines of catalogDoc.
const (
	catalogBegin = "<!-- The code catalog below is generated from findings/registry.json by go generate ./internal/guarantees. Do not edit it by hand. -->"
	catalogEnd   = "<!-- The end of the generated code catalog. -->"
)

func jsonString(s string) string {
	b, err := json.Marshal(s)
	if err != nil {
		panic(err)
	}
	return string(b)
}

// statementIndex is spec/statements.json for stmts, which are in
// identifier order: one object per statement, one statement per line, so
// two changes that take the same identifier edit the same line (ADR-011
// D3 item 7).
func statementIndex(stmts []statement) []byte {
	var b bytes.Buffer
	b.WriteString("{\n  \"statements\": [")
	for i, s := range stmts {
		if i > 0 {
			b.WriteByte(',')
		}
		status := "active"
		if !s.active() {
			status = "withdrawn"
		}
		fmt.Fprintf(&b, "\n    {\"id\": %s, \"chapter\": %s, \"section\": %s, \"kind\": %s, \"since\": %s, \"observable\": %t, \"status\": %s",
			jsonString(s.ID), jsonString(s.File), jsonString(s.Section), jsonString(s.Kind), jsonString(s.Since), s.Observable, jsonString(status))
		if len(s.AmendedBy) > 0 {
			quoted := make([]string, len(s.AmendedBy))
			for k, e := range s.AmendedBy {
				quoted[k] = jsonString(e)
			}
			fmt.Fprintf(&b, ", \"amended_by\": [%s]", strings.Join(quoted, ", "))
		}
		b.WriteByte('}')
	}
	if len(stmts) > 0 {
		b.WriteString("\n  ")
	}
	b.WriteString("]\n}\n")
	return b.Bytes()
}

// catalogTable is the code catalog for the registry: one row per code, in
// the registry's order, each statement linked to its anchor.
func catalogTable(codes []registryCode, stmts []statement) string {
	where := map[string]string{}
	for _, s := range stmts {
		if _, dup := where[s.ID]; !dup {
			where[s.ID] = s.File
		}
	}
	var b strings.Builder
	b.WriteString("| Code | Severity | Class | Subject | Parameters | Since | Statements |\n")
	b.WriteString("|---|---|---|---|---|---|---|\n")
	for _, c := range codes {
		var always, optional []string
		for _, p := range c.Params {
			if p.Always {
				always = append(always, "`"+p.Name+"`")
			} else {
				optional = append(optional, "`"+p.Name+"`")
			}
		}
		params := strings.Join(always, ", ")
		if len(optional) > 0 {
			if params != "" {
				params += "; "
			}
			params += "optional: " + strings.Join(optional, ", ")
		}
		since := c.Since
		if c.Retired != "" {
			since += ", retired " + c.Retired
		}
		var links []string
		for _, id := range c.Statements {
			if file, ok := where[id]; ok {
				links = append(links, fmt.Sprintf("[%s](%s#%s)", id, file, strings.ToLower(id)))
			} else {
				links = append(links, id)
			}
		}
		fmt.Fprintf(&b, "| `%s` | %s | %s | %s | %s | %s | %s |\n",
			c.Code, c.Severity, c.Class, c.Subject, orDash(params), since, orDash(strings.Join(links, ", ")))
	}
	return b.String()
}

func orDash(s string) string {
	if s == "" {
		return "—"
	}
	return s
}

// withCatalog returns doc with the lines between its catalog markers
// replaced by table.
func withCatalog(doc []byte, table string) ([]byte, error) {
	text := string(doc)
	begin := strings.Count(text, catalogBegin+"\n")
	end := strings.Count(text, "\n"+catalogEnd+"\n")
	if begin != 1 || end != 1 {
		return nil, fmt.Errorf("%s: the catalog markers appear %d and %d times, not once each", catalogDoc, begin, end)
	}
	i := strings.Index(text, catalogBegin+"\n") + len(catalogBegin) + 1
	j := strings.Index(text, "\n"+catalogEnd+"\n") + 1
	if j < i {
		return nil, fmt.Errorf("%s: the catalog's end marker comes before its beginning", catalogDoc)
	}
	return []byte(text[:i] + table + text[j:]), nil
}

// generated is what root's two generated files should hold, by their
// path below root.
func generated(root string) (map[string][]byte, error) {
	docs, err := readDocs(root)
	if err != nil {
		return nil, err
	}
	stmts, _ := specStatements(docs)
	codes, err := readRegistry(root)
	if err != nil {
		return nil, err
	}
	chapter, err := os.ReadFile(filepath.Join(root, catalogDoc))
	if err != nil {
		return nil, err
	}
	withTable, err := withCatalog(chapter, catalogTable(codes, stmts))
	if err != nil {
		return nil, err
	}
	return map[string][]byte{statementsFile: statementIndex(stmts), catalogDoc: withTable}, nil
}

// staleProblem compares the committed file name below root with want.
func staleProblem(root, name string, want []byte) []string {
	got, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(name)))
	if err != nil {
		return []string{err.Error()}
	}
	if !bytes.Equal(got, want) {
		return []string{fmt.Sprintf("spec/%s differs from what the specification generates; run go generate ./internal/guarantees", name)}
	}
	return nil
}

// indexProblems is TestStatementIndex's check.
func indexProblems(root string) []string {
	docs, err := readDocs(root)
	if err != nil {
		return []string{err.Error()}
	}
	stmts, _ := specStatements(docs)
	return staleProblem(root, statementsFile, statementIndex(stmts))
}

// catalogProblems is TestFindingCatalog's check.
func catalogProblems(root string) []string {
	g, err := generated(root)
	if err != nil {
		return []string{err.Error()}
	}
	return staleProblem(root, catalogDoc, g[catalogDoc])
}

// TestGenerateSpec is the generator go generate runs. Without
// -spec.generate it does nothing.
func TestGenerateSpec(t *testing.T) {
	if !*generateSpec {
		t.Skip("run by go generate ./internal/guarantees")
	}
	g, err := generated(specRoot)
	if err != nil {
		t.Fatal(err)
	}
	for name, b := range g {
		if err := os.WriteFile(filepath.Join(specRoot, filepath.FromSlash(name)), b, 0o644); err != nil {
			t.Fatal(err)
		}
	}
}

// TestStatementIndex is ADR-011 D14's tripwire over spec/.
func TestStatementIndex(t *testing.T) {
	report(t, indexProblems(specRoot))
}

// TestFindingCatalog is ADR-011 D14's tripwire over spec/.
func TestFindingCatalog(t *testing.T) {
	report(t, catalogProblems(specRoot))
}
